package com.example.mhnfe.ui.screens.monitoring.kvsimport android.content.Contextimport android.graphics.Bitmapimport android.util.Logimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.example.mhnfe.domain.ai.BoundingBoxUtilsimport com.example.mhnfe.domain.ai.DetectionManagerimport com.example.mhnfe.domain.ai.opencv.BitmapToMatConverterimport com.example.mhnfe.domain.ai.opencv.MotionDetectorimport com.example.mhnfe.domain.ai.yolo.BoundingBoximport com.example.mhnfe.domain.ai.yolo.YoloDetectionManagerimport dagger.hilt.android.lifecycle.HiltViewModelimport dagger.hilt.android.qualifiers.ApplicationContextimport kotlinx.coroutines.launchimport org.opencv.core.Matimport org.opencv.core.Rectimport javax.inject.Inject@HiltViewModelclass AiViewModel @Inject constructor(    @ApplicationContext private val context: Context, // Context 주입) : ViewModel() {    private val tag = "AiViewModel"    private val motionDetector = MotionDetector()    private val yoloDetectionManager = YoloDetectionManager(context)    private var boundingBoxes: List<BoundingBox> = listOf()    fun processFrame(bitmap: Bitmap?) {        viewModelScope.launch {            try {                bitmap?.let { bmp ->                    Log.d(tag, "Frame received: ${bmp.width}x${bmp.height}")                    // Bitmap을 Mat으로 변환                    val currentFrame: Mat = BitmapToMatConverter.BitToMat(bmp)                    // OpenCV로 움직임 감지                    val motionAreas: List<Rect> = motionDetector.detectMotion(currentFrame)                    // 감지된 움직임 영역을 로그에 출력                    if (motionAreas.isNotEmpty()) {                        Log.d(tag, "Motion detected in ${motionAreas.size} area(s)")                        // Yolo 실행                        yoloDetectionManager.detect(bmp)                    } else {                        Log.d(tag, "No motion detected")                    }                    // 현재 프레임 객체 해제                    currentFrame.release()                }            } catch (e: Exception) {                Log.e(tag, "Frame processing error", e)            }        }    }    fun detectEvent(onResult: (Int, String, String, String)  -> Unit) {        viewModelScope.launch {            try {                Log.d("DetectEvent", "detectEvent() 시작")                val trackingId = DetectionManager.getNextTrackingId()                val coordinatesJson = BoundingBoxUtils.coordinatesJson(boundingBoxes)                val objectName = BoundingBoxUtils.objectNameJson(boundingBoxes)                val confidence = BoundingBoxUtils.confidenceJson(boundingBoxes)                onResult(trackingId, coordinatesJson, objectName, confidence)            } catch (e: Exception) {                Log.e("DetectEvent", "detectEvent() 중 오류 발생: ${e.message}", e)            }        }    }}